# Vybe DRIVER app - UI v2 (accept fix + font sizing)
$root = "C:\Users\Lenovo\Documents\home\user\zip-rick\apps\driver_app"
if (-not (Test-Path $root)) { Write-Host "driver_app not found" -ForegroundColor Red; exit 1 }
$bk = Join-Path $root ("ui_backup_" + (Get-Date -Format "yyyyMMdd-HHmmss"))
